on conflict (item_id) do update
  set art_svg = excluded.art_svg, updated_at = now()
  where public.home_item_art.art_svg is distinct from excluded.art_svg;

-- ── 3. The aspects ───────────────────────────────────────────────────────
update public.home_items h
   set art_aspect = v.aspect
  from (values
  ('cp2612_snow_globe', 1),
  ('cp2612_ornament_tree', 0.75),
  ('cp2612_window_snow', 0.9),
  ('cp2612_poster_first_frost', 0.8),
  ('cp2612_icicle_lights', 4),
  ('cp2612_pillow_knit', 1.2),
  ('cp2612_rug_snowflake', 3.003),
  ('cp2612_rack_ice_palace', 1.25)
  ) as v(id, aspect)
 where h.id = v.id
   and h.art_aspect is distinct from v.aspect;

notify pgrst, 'reload schema';
